function iopEnvironment(array $env): array {
    $base=getenv();if(!is_array($base))throw new TestFailure('SETUP_FAILURE env');
    foreach(array_keys($base) as $key)if(str_starts_with($key,'FMONITOR_DB_')
        ||in_array($key,['FMONITOR_PROCESS_TABLE_PREFIX','FMONITOR_BOOTSTRAP_SUPERADMIN_PASSWORD'],true))unset($base[$key]);
    return array_replace($base,$env);
}
function iopRun(string$cli,array$env,array$args=['--email','owner@shlz.ru']):array{
    $pipes=[];
    $p=proc_open([PHP_BINARY,$cli,...$args],[0=>['file','/dev/null','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname($cli,2),iopEnvironment($env));
    if(!is_resource($p))throw new TestFailure('SETUP_FAILURE CLI');$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);return[proc_close($p),$out,$err];
}
function iopLocalRun(string$cli,array$env,string$email='owner@shlz.ru'):array{return iopRun($cli,$env,['--resume-existing-local','--email',$email]);}
function iopStart(string$cli,array$env,array$args=['--email','owner@shlz.ru']):array{$pipes=[];$p=proc_open([PHP_BINARY,$cli,...$args],[0=>['file','/dev/null','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname($cli,2),iopEnvironment($env));if(!is_resource($p))throw new TestFailure('SETUP_FAILURE concurrent CLI');return[$p,$pipes];}
function iopStartLocal(string$cli,array$env):array{return iopStart($cli,$env,['--resume-existing-local','--email','owner@shlz.ru']);}
function iopFinish(array$child):array{[$p,$pipes]=$child;stream_set_blocking($pipes[1],false);stream_set_blocking($pipes[2],false);$out='';$err='';$deadline=microtime(true)+10;do{$out.=stream_get_contents($pipes[1]);$err.=stream_get_contents($pipes[2]);$status=proc_get_status($p);if(!$status['running'])break;if(microtime(true)>=$deadline){proc_terminate($p,9);throw new TestFailure('SETUP_FAILURE concurrent CLI timeout');}usleep(10000);}while(true);$out.=stream_get_contents($pipes[1]);$err.=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$closed=proc_close($p);return[$status['exitcode']>=0?$status['exitcode']:$closed,$out,$err];}
